from __future__ import annotations


class Group:
    def __init__(self, members: list[str]) -> None:
        self.members: list[str] = list(members)
        # Store balances in integer cents to avoid floating-point inaccuracies
        self._balances: dict[str, int] = {m: 0 for m in self.members}

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if amount <= 0:
            raise ValueError("Expense amount must be strictly positive.")

        if payer not in self._balances:
            self.members.append(payer)
            self._balances[payer] = 0

        if participants is None:
            parts = list(self.members)
        else:
            parts = list(participants)
            for p in parts:
                if p not in self._balances:
                    self.members.append(p)
                    self._balances[p] = 0

        if not parts:
            return

        total_cents = round(amount * 100)
        n = len(parts)
        share_cents = total_cents // n

        # Every non-payer participant owes exactly `amount rounded down to the cent`.
        # The remainder cents are borne by the payer.
        # If the payer is among participants, payer's share absorbs the leftover cents.
        # If payer is not among participants, the participants still only pay `share_cents`,
        # and the payer absorbs the remainder (i.e. is only reimbursed for what participants owe).
        total_collected = 0
        for p in parts:
            if p != payer:
                self._balances[p] -= share_cents
                total_collected += share_cents

        self._balances[payer] += total_collected

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        return {m: self._balances[m] / 100.0 for m in self.members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        # Debtors (net negative) and creditors (net positive)
        debtors: list[list[str | int]] = []
        creditors: list[list[str | int]] = []

        for m in self.members:
            b = self._balances[m]
            if b < 0:
                debtors.append([m, -b])
            elif b > 0:
                creditors.append([m, b])

        payments: list[tuple[str, str, float]] = []

        d_idx = 0
        c_idx = 0

        while d_idx < len(debtors) and c_idx < len(creditors):
            debtor, d_amt = debtors[d_idx]
            creditor, c_amt = creditors[c_idx]

            transfer = min(d_amt, c_amt)
            if transfer >= 100:  # Payments smaller than 1.00 are written off
                payments.append((str(debtor), str(creditor), transfer / 100.0))

            debtors[d_idx][1] = d_amt - transfer
            creditors[c_idx][1] = c_amt - transfer

            if debtors[d_idx][1] == 0:
                d_idx += 1
            if creditors[c_idx][1] == 0:
                c_idx += 1

        return payments
